@router.get("/reporting/dashboards/find")
async def find_analytics_dashboards(
    category: str = Query(...),
    current_user: User = Depends(get_current_user)
):
    dashboards = AnalyticsDashboard.find(
        (AnalyticsDashboard.category == category) &
        (AnalyticsDashboard.organization_id == current_user.organization_id)
    ).all()
    return [{"pk": d.pk, "title": d.title, "layout": d.layout_config} for d in dashboards]
